#pseudo-absences will be randomly generated by sampling across the study area, excluding presence 
#locations and their neighbours

pseudo_absences_shp <- function(df, shapefile) {
  presences_polygons_id = which(shapefile$LocationCo %in% df$nutsM_code)
  presences_polygons <-  shapefile[presences_polygons_id,]
  adj_polygons_list <- st_intersects(presences_polygons, shapefile)
  adj_polygons_id <- unique(unlist(adj_polygons_list))
  remove_ids <- unique(c(presences_polygons_id, adj_polygons_id))
  pseudo_absences_shapefile <- shapefile[-remove_ids, ]
  return(pseudo_absences_shapefile)
}